    input[strcspn(input, "\n")] = 0;
    int hashed_input = hash(input);
    printf("The hash of '%s' is: %d\n", input, hashed_input);
    free(input);
    return 0;
}

int hash(char* str) {
    int hash = 0;
    int len = strlen(str);
    for (int i = 0; i < len; i++) {
        hash += PRIME1 * PRIME2 * str[i];
    }
    return hash;
}

