void decimalToBinary(int decimalNum, int binaryArr[]) {
    int index = 0;
    while (decimalNum != 0) {
        binaryArr[index] = decimalNum % 2;
        decimalNum = decimalNum / 2;
        index++;
    }
}

// Function to get decimal number from binary array
int binaryToDecimal(int binaryArr[]) {
    int decimalNum = 0;
    int power = 1;
    for (int i = 0; i < 8; i++) {
